-- Wendy Walsh (profileID=23) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Wendy Walsh phrasings

SELECT p.argumentID, p.phrasingID, 23, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 23
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 23 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=23 AND targArgID IN (101,103,105,107,123,134,145,161,165,192,230,288,297,322,349,400,412,428,546,560,561,611,612,615,616,617,651,652,777,844,897,898,901,902,910,920,1237,1275,1385,1387,1410,1440);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 23
SET pe.active = o.acceptance
WHERE pe.profileID = 23;

SELECT 'Done: endorsements for profileID=23' AS status;